//! Rust and TypeScript must agree byte for byte, so both read the SAME golden file:
//! packages/types/fixtures/wire.json, generated by `pnpm fixtures:wire`.
//! If this test fails after a codec change, the contract changed and both sides plus the
//! fixtures must be updated in one commit.
use bsa_sentry_core::wire::{decode_credentials, decode_policy, encode_policy, encode_state, DeviceState, WireError};
use bsa_sentry_core::{Counters, Session};
use serde_json::Value;

fn fixtures() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../packages/types/fixtures/wire.json");
    let text = std::fs::read_to_string(path).expect("run `pnpm fixtures:wire` first");
    serde_json::from_str(&text).unwrap()
}

fn bytes(hex_str: &str) -> Vec<u8> {
    hex::decode(hex_str.trim_start_matches("0x")).unwrap()
}

fn addr(s: &str) -> [u8; 20] {
    bytes(s).try_into().unwrap()
}

fn u64_of(v: &Value) -> u64 {
    v.as_str().unwrap().parse().unwrap()
}

#[test]
fn the_limits_match_the_typescript_side() {
    let f = fixtures();
    let l = &f["limits"];
    assert_eq!(l["MAX_PAYEES"].as_u64().unwrap() as usize, bsa_sentry_core::wire::MAX_PAYEES);
    assert_eq!(l["MAX_LABEL_BYTES"].as_u64().unwrap() as usize, bsa_sentry_core::wire::MAX_LABEL_BYTES);
    assert_eq!(l["MAX_CLAIMS"].as_u64().unwrap() as usize, bsa_sentry_core::wire::MAX_CLAIMS);
    assert_eq!(l["MAX_CLAIM_BYTES"].as_u64().unwrap() as usize, bsa_sentry_core::wire::MAX_CLAIM_BYTES);
    assert_eq!(l["MAX_AGENT_NAME_BYTES"].as_u64().unwrap() as usize, bsa_sentry_core::wire::MAX_AGENT_NAME_BYTES);
}

#[test]
fn every_policy_fixture_decodes_to_the_recorded_structure() {
    let f = fixtures();
    let cases = f["policies"].as_array().unwrap();
    assert_eq!(cases.len(), 4, "expected demo / empty / full-8-payees / field-maxima");

    for case in cases {
        let name = case["name"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        let want = &case["decoded"];
        let got = decode_policy(&blob).unwrap_or_else(|e| panic!("{name}: {e:?}"));

        assert_eq!(got.active, want["active"].as_bool().unwrap(), "{name}: active");
        assert_eq!(got.chain_id, u64_of(&want["chainId"]), "{name}: chainId");
        assert_eq!(got.token, addr(want["token"].as_str().unwrap()), "{name}: token");
        assert_eq!(got.auto_max, u64_of(&want["autoMax"]), "{name}: autoMax");
        assert_eq!(got.hard_max, u64_of(&want["hardMax"]), "{name}: hardMax");
        assert_eq!(got.budget, u64_of(&want["budget"]), "{name}: budget");
        assert_eq!(got.max_count as u64, want["maxCount"].as_u64().unwrap(), "{name}: maxCount");

        let want_payees = want["payees"].as_array().unwrap();
        assert_eq!(got.payee_count, want_payees.len(), "{name}: payee count");
        for (i, wp) in want_payees.iter().enumerate() {
            let gp = &got.payees()[i];
            assert_eq!(gp.addr, addr(wp["address"].as_str().unwrap()), "{name}: payee {i} address");
            assert_eq!(gp.label(), wp["label"].as_str().unwrap().as_bytes(), "{name}: payee {i} label");
        }
    }
}

#[test]
fn every_policy_fixture_re_encodes_to_the_exact_same_bytes() {
    let f = fixtures();
    for case in f["policies"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        let policy = decode_policy(&blob).unwrap();
        let mut out = [0u8; 512];
        let n = encode_policy(&policy, &mut out).unwrap();
        assert_eq!(&out[..n], &blob[..], "{name}: re-encoding changed the bytes");
    }
}

#[test]
fn every_state_fixture_round_trips() {
    let f = fixtures();
    for case in f["states"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        let want = &case["decoded"];

        // The device produces states; it never parses one. Rebuild it from the recorded
        // fields and check the bytes match what TypeScript expects to receive.
        // The state header is 21 bytes plus the last-payment label; the policy runs to the end.
        let label_len = blob[20] as usize;
        let policy = decode_policy(&blob[21 + label_len..])
            .unwrap_or_else(|e| panic!("{name}: nested policy: {e:?}"));

        let last = &want["lastPayment"];
        let state = DeviceState {
            session: Session { armed: want["sessionArmed"].as_bool().unwrap() },
            has_credentials: want["hasCredentials"].as_bool().unwrap(),
            counters: Counters {
                spent: u64_of(&want["spent"]),
                count: want["count"].as_u64().unwrap() as u16,
            },
            last_value: if last.is_null() { 0 } else { u64_of(&last["value"]) },
            last_label: {
                let mut buf = [0u8; bsa_sentry_core::wire::MAX_LABEL_BYTES];
                let mut len = 0usize;
                if !last.is_null() {
                    let l = last["label"].as_str().unwrap().as_bytes();
                    len = l.len();
                    buf[..len].copy_from_slice(l);
                }
                (buf, len)
            },
            policy,
        };

        let mut out = [0u8; 512];
        let n = encode_state(&state, &mut out).unwrap();
        assert_eq!(&out[..n], &blob[..], "{name}: encoded state differs from the fixture");
    }
}

#[test]
fn every_credentials_fixture_decodes_to_the_recorded_structure() {
    let f = fixtures();
    for case in f["credentials"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        let want = &case["decoded"];
        let got = decode_credentials(&blob).unwrap_or_else(|e| panic!("{name}: {e:?}"));

        let wa = &want["attestation"];
        assert_eq!(got.attestation.subject, addr(wa["subject"].as_str().unwrap()), "{name}: subject");
        assert_eq!(got.attestation.claim(), wa["claim"].as_str().unwrap().as_bytes(), "{name}: claim");
        assert_eq!(got.attestation.issued_at, u64_of(&wa["issuedAt"]), "{name}: issuedAt");
        assert_eq!(got.attestation.expires_at, u64_of(&wa["expiresAt"]), "{name}: expiresAt");
        assert_eq!(got.attestation.evidence.to_vec(), bytes(wa["evidence"].as_str().unwrap()), "{name}: evidence");
        assert_eq!(got.attestation_sig.to_vec(), bytes(want["attestationSig"].as_str().unwrap()), "{name}: attestationSig");

        let wd = &want["delegation"];
        assert_eq!(got.delegation.agent, addr(wd["agent"].as_str().unwrap()), "{name}: agent");
        assert_eq!(got.delegation.agent_name(), wd["agentName"].as_str().unwrap().as_bytes(), "{name}: agentName");
        assert_eq!(got.delegation.attestation.to_vec(), bytes(wd["attestation"].as_str().unwrap()), "{name}: delegation.attestation");
        assert_eq!(got.delegation.expires_at, u64_of(&wd["expiresAt"]), "{name}: delegation.expiresAt");
        assert_eq!(got.delegation.nonce.to_vec(), bytes(wd["nonce"].as_str().unwrap()), "{name}: nonce");
        assert_eq!(got.delegation_sig.to_vec(), bytes(want["delegationSig"].as_str().unwrap()), "{name}: delegationSig");

        let want_claims = wd["claims"].as_array().unwrap();
        assert_eq!(got.delegation.claim_count as usize, want_claims.len(), "{name}: claim count");
        for (i, wc) in want_claims.iter().enumerate() {
            assert_eq!(got.delegation.claim(i), wc.as_str().unwrap().as_bytes(), "{name}: claim {i}");
        }
    }
}

#[test]
fn the_device_rejects_every_policy_blob_typescript_rejects() {
    let f = fixtures();
    for case in f["invalid"]["policies"].as_array().unwrap() {
        let why = case["why"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        assert!(decode_policy(&blob).is_err(), "should have been rejected: {why}");
    }
}

#[test]
fn the_device_rejects_every_credentials_blob_typescript_rejects() {
    let f = fixtures();
    for case in f["invalid"]["credentials"].as_array().unwrap() {
        let why = case["why"].as_str().unwrap();
        let blob = bytes(case["hex"].as_str().unwrap());
        assert!(decode_credentials(&blob).is_err(), "should have been rejected: {why}");
    }
}

#[test]
fn trailing_bytes_are_refused_so_a_ninth_payee_cannot_hide_after_the_policy() {
    let f = fixtures();
    let demo = bytes(f["policies"][0]["hex"].as_str().unwrap());
    let mut smuggled = demo.clone();
    smuggled.extend_from_slice(&[0x11; 21]); // a whole extra payee
    assert_eq!(decode_policy(&smuggled), Err(WireError::TrailingBytes));
}

#[test]
fn a_policy_decodes_the_same_whether_or_not_it_is_active() {
    let f = fixtures();
    let demo = bytes(f["policies"][0]["hex"].as_str().unwrap());
    let mut inactive = demo.clone();
    inactive[1] = 0;
    assert!(decode_policy(&demo).unwrap().active);
    assert!(!decode_policy(&inactive).unwrap().active);
    assert_eq!(decode_policy(&demo).unwrap().payee_count, decode_policy(&inactive).unwrap().payee_count);
}
